function fresh(){return{format:'SAMI-PROJECT-2',name:'Untitled site',meta:{},area:null,features:[],base:'street',map:{center:{lat:52.5862,lng:-2.1288},zoom:16},hiddenTypes:[],serviceVisibility:Object.fromEntries(Object.keys(SERVICES).map(k=>[k,true])),route:{product:'lion',...PRODUCTS.lion,lanes:1},asset:{kind:'welfare',...ASSETS.welfare,angle:0},serviceType:'electric'};}
