 $$('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));$$('[data-base]').forEach(b=>b.onclick=()=>switchBase(b.dataset.base));$$('[data-drawer]').forEach(b=>b.onclick=()=>state.drawer===b.dataset.drawer?closeDrawer():openDrawer(b.dataset.drawer));
 $('#closeDrawer').onclick=closeDrawer;$('#areaChip').onclick=()=>openDrawer('area');$('#locateBtn').onclick=locate;$('#fitBtn').onclick=fitProject;$('#lockBtn').onclick=()=>setLock(!isLocked());$('#zoomInBtn').onclick=()=>state.map.zoomIn();$('#zoomOutBtn').onclick=()=>state.map.zoomOut();
 $('#undoBtn').onclick=undo;$('#redoBtn').onclick=redo;$('#finishDrawBtn').onclick=finishDraw;$('#cancelDrawBtn').onclick=cancelDraw;$('#backPointBtn').onclick=backPoint;
