 $('#startFindBtn').onclick=()=>{dismissWelcome();openDrawer('search');};$('#dismissWelcome').onclick=dismissWelcome;
 $('#sendBtn').onclick=handleAskButton;$('#askInput').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();sendAsk();}};$('#askInput').oninput=updateAskLabel;
 $('#closeSami').onclick=()=>$('#samiPanel').classList.remove('open');$('#muteSami').onclick=()=>{setPref('sami.voice.output',readPref('sami.voice.output')==='off'?'on':'off');if(readPref('sami.voice.output')==='off')window.speechSynthesis?.cancel();updateVoiceButton();};
