 const wasPlan=state.mode==='plan';state.mode=mode;setModeUI(mode);
 if(mode==='plan'){switchBase('drawing',false);fitArea();}else if(wasPlan){switchBase(state.mapView?.base||state.project.base||'street',false);if(state.mapView)state.map.setView(state.mapView.center,state.mapView.zoom);}
